import{_ as e,c as t,o,ad as l}from"./chunks/framework.DGbM31vj.js";const p=JSON.parse('{"title":"MCP","description":"","frontmatter":{"title":"MCP"},"headers":[],"relativePath":"feature/mcp.md","filePath":"feature/mcp.md","lastUpdated":1788143555000}'),r={name:"feature/mcp.md"};function c(i,a,n,d,s,m){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h1><p>MCP（Model Context Protocol）让支持 MCP 的 AI 客户端以工具调用的方式访问下载器。当前实现提供应用配置管理、内容解析与下载、微信视频号查询，以及下载任务、账号、浏览记录、日志和证书状态等本地数据查询能力。</p><p>下载器支持两种接入方式：</p><ul><li><strong>Streamable HTTP（推荐）</strong>：使用主服务的 <code>/mcp</code> 端点。内置 MCP 直接访问当前进程中的数据库和运行时服务。</li><li><strong>stdio</strong>：由 AI 客户端启动 <code>wx_video_download mcp</code> 子进程，再通过已经运行的下载器 API 完成操作。</li></ul><p>两种接入方式提供相同的 MCP 工具。需要更完整的 stdio 配置与视频号外部下载说明，可参阅 <a href="/wx_channels_download/cli/mcp.html">MCP Server 命令行文档</a>。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li><a href="./mcp/enable.html">启用</a></li><li><a href="./mcp/commands.html">命令</a></li></ul><h3 id="常用场景" tabindex="-1">常用场景 <a class="header-anchor" href="#常用场景" aria-label="Permalink to &quot;常用场景&quot;">​</a></h3><ul><li><a href="./mcp/scenarios/change-download-directory.html">修改下载目录</a></li><li><a href="./mcp/scenarios/fetch-and-download.html">解析链接并下载</a></li><li><a href="./mcp/scenarios/query-account-content.html">查询账号内容和浏览记录</a></li><li><a href="./mcp/scenarios/troubleshoot-download.html">排查下载失败</a></li><li><a href="./mcp/scenarios/external-downloader.html">使用第三方下载器保存视频号视频</a></li></ul>',9)])])}const _=e(r,[["render",c]]);export{p as __pageData,_ as default};
